from pathlib import Path

import pytest


def read_note(name: str) -> str:
    """Return the text of file `name` inside the `notes` directory.

    `notes` is resolved relative to the current working directory. `name` is
    untrusted. The result is the file's text (UTF-8), or "" if the file is
    missing, is not a regular file, or cannot be read or decoded. A name that
    would resolve outside `notes` (via "..", an absolute path, a symlink, an
    embedded NUL, or any other spelling) also yields "" and never reads that
    file.
    """
    if not name or "\x00" in name:
        return ""
    try:
        base = Path("notes").resolve()
        target = (base / name).resolve()
        if target == base or not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes").mkdir()
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_existing_note(sandbox: Path) -> None:
    (sandbox / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("a.txt") == "hello"


def test_reads_unicode_note(sandbox: Path) -> None:
    (sandbox / "notes" / "u.txt").write_text("héllo ✓", encoding="utf-8")
    assert read_note("u.txt") == "héllo ✓"


def test_reads_nested_note_inside_notes(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    (sandbox / "notes" / "sub" / "b.txt").write_text("nested", encoding="utf-8")
    assert read_note("sub/b.txt") == "nested"


def test_missing_file_gives_empty(sandbox: Path) -> None:
    assert read_note("nope.txt") == ""


def test_empty_name_gives_empty(sandbox: Path) -> None:
    assert read_note("") == ""


def test_directory_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    assert read_note("sub") == ""
    assert read_note(".") == ""


def test_dotdot_traversal_blocked(sandbox: Path) -> None:
    (sandbox / "secret.txt").write_text("top secret", encoding="utf-8")
    assert read_note("../secret.txt") == ""
    assert read_note("sub/../../secret.txt") == ""
    assert read_note("./../secret.txt") == ""


def test_sibling_directory_with_same_prefix_blocked(sandbox: Path) -> None:
    (sandbox / "notes2").mkdir()
    (sandbox / "notes2" / "x.txt").write_text("sibling", encoding="utf-8")
    assert read_note("../notes2/x.txt") == ""


def test_absolute_path_blocked(sandbox: Path) -> None:
    secret = sandbox / "secret.txt"
    secret.write_text("top secret", encoding="utf-8")
    assert read_note(str(secret)) == ""
    assert read_note("/etc/passwd") == ""


def test_symlink_escaping_notes_blocked(sandbox: Path) -> None:
    secret = sandbox / "secret.txt"
    secret.write_text("top secret", encoding="utf-8")
    link = sandbox / "notes" / "link.txt"
    try:
        link.symlink_to(secret)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("link.txt") == ""


def test_symlinked_directory_escaping_notes_blocked(sandbox: Path) -> None:
    outside = sandbox / "outside"
    outside.mkdir()
    (outside / "s.txt").write_text("top secret", encoding="utf-8")
    link = sandbox / "notes" / "d"
    try:
        link.symlink_to(outside, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("d/s.txt") == ""


def test_nul_byte_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("a.txt\x00../../secret.txt") == ""
    assert read_note("\x00") == ""


def test_undecodable_file_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "bin.dat").write_bytes(b"\xff\xfe\xfa\x80")
    assert read_note("bin.dat") == ""


def test_missing_notes_directory_gives_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_note("a.txt") == ""
